      const names=new Set(array(introducedNames(record)).map(name=>name.symbol_id)),stores=[];
      for(const value of layers){const layer=resolveEvidence(value),obj=proofResult(layer.fields?.obj);if(layer.type!=="ReleaseOneStructLayerProof"||obj.kind!=="symbol_reference"||!names.has(obj.symbol_id)||!Array.isArray(layer.fields?.store_and_infer))return null;stores.push(...layer.fields.store_and_infer);}
