          detail.addEventListener("toggle",()=>{if(detail.open&&!shown){shown=true;const container=element("div");detail.append(container);if(action&&resolveEvidence(action.record)===assignment&&action.statementId===fact.producer_statement_id)appendProcessFrame(container,fact,action,depth);else container.append(element("p","lr-empty-note",editText("此取值的局部条件未完整导出。","The local conditions for this assignment were not fully exported.")));positionOverlays();}});
