      if(["definition-condition","structure-condition","template-premise","structure-field","interface-goal"].includes(action.kind))return {"definition-condition":["定义条件 ▸","Defining condition ▸"],"structure-condition":["结构条件 ▸","Structural condition ▸"],"template-premise":["实例化前提 ▸","Instantiation premise ▸"],"structure-field":["字段范围 ▸","Field domain ▸"],"interface-goal":["目标 ▸","Goal ▸"]}[action.kind][lang()==="zh"?0:1];
