          formation.addEventListener("toggle",()=>{if(formation.open&&!shown){shown=true;appendAtomicWellDefinedness(formation,views[0],statement.evidence,0,null,"arguments");for(const view of views)appendAtomicWellDefinedness(formation,view,statement.evidence,0,null,"conclusion");positionOverlays();}});return;
